import csv
from common import *
from research_pass25 import base,hybrid


def main():
    a=json.loads((HERE/'feasibility.json').read_text());screen=json.loads((HERE/'screen.json').read_text());analysis=json.loads((HERE/'analysis.json').read_text());memory=json.loads((HERE/'memory.json').read_text());validation=json.loads((HERE/'validation.json').read_text())
    def point(name,preset,variant):return next(r for r in screen['rows'] if r['image']==name and r['preset']==preset and r['variant']==variant)
    def initial(name,variant,step=None):return next(r for r in a['rows'] if r['image']==name and r['variant']==variant and r['step']==step)
    def save(name,lines):(HERE/name).write_text('\n'.join(lines)+'\n',encoding='utf-8',newline='\n')
    lines=['# Pass 25 transform initialization feasibility','','Initialization-only feasibility passes on text and photography, but not consistently across all four inputs. This is a representation screen, not proof of a complete hybrid advantage. Source starts at 4b41f1794d005241444e825c2b6ce125ed135e7f; unchanged practical control pbc31_feature_histogram at 1c9c4016fdb213d7d16663542d268c7c3df4ed9b.','','Ordinary preprocessing is unchanged: EXIF-transposed RGB, conversion to YCbCr before normal PIL bicubic downsampling at the 250k cap. Ordinary initialization begins at rounded component means and selects/applies the normal 3 full-image grids. Fresh initialization selection and production entropy exactly reproduce saved Quality and HQ initialization-only prefixes for all 4 images. No ordinary iterative corrections are included here.','','| Image | Working size | Ordinary init bytes | Init / full Q bytes | Init / full HQ bytes | Init working YCbCr MSE | Init source RGB MSE |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for name in IMAGES:
        r=initial(name,'ordinary');parent=next(p for p in a['parents'] if p['image']==name);q=point(name,'quality','ordinary');hq=point(name,'high_quality','ordinary')
        lines.append(f"| {name} | {parent['working_size'][0]}x{parent['working_size'][1]} | {r['bytes']:,} | {100*r['bytes']/q['bytes']:.2f}% | {100*r['bytes']/hq['bytes']:.2f}% | {r['working_component_mse']:.3f} | {r['rgb_mse']:.3f} |")
    lines+=['','These ratios compare separately compressed initialization-only and full files. They are not additive ownership of bytes inside the full LZMA stream. Raw patch-bit counts are recorded separately; final bytes are the rate metric. Initial errors include actual signed reconstruction, clipping/color conversion and source-size bicubic resize.','','One transform design: each native working component minus its rounded global mean; edge padding; float32 orthonormal 8x8 type-II SciPy DCT; nearest integer signed int16 coefficients at the fixed steps 64/128/256. Exact Pass21 R21V zero-gap/zigzag frequency-plane serialization and XZ0, with no entropy tuning. No original-resolution transform, back-projection, chroma subsampling or second color transform.','','P25I uses a 24-byte little-endian <4sHHHHB3BfI> header: magic, working width/height, original width/height, color ID, 3 byte means, float32 step and entropy payload length. The XZ payload contains bounded R21V counts and coefficients. Decode reconstructs float32 IDCT at working resolution, adds means, rounds to signed int16 without color-range clipping, then normal PBC output conversion/resize. This exact stored-data canvas starts refinement in the later test. No encoder weights or source image are needed.','','| Image | Representation / step | Final init bytes | Source RGB MSE | Working component MSE | Working RGB MSE |','| --- | --- | ---: | ---: | ---: | ---: |']
    for r in a['rows']:
        label=r['variant']+((' / '+str(r['step'])) if r['step'] is not None else '')
        lines.append(f"| {r['image']} | {label} | {r['bytes']:,} | {r['rgb_mse']:.3f} | {r['working_component_mse']:.3f} | {r['working_rgb_mse']:.3f} |")
    lines+=['','Working component error for ordinary/DCT is YCbCr error against the clipped decoded working canvas. JPEG component error re-expresses its decoded RGB in YCbCr; working RGB MSE provides the common display-domain comparison. Working canvas differences from ordinary initialization are in feasibility.json.','','The single initial JPEG reference is quality 1, 4:2:0, optimize=True,progressive=False, chosen before transform results for the low 4-12k initialization budgets. It is a normal JPEG at working resolution plus a 14-byte standard COM segment carrying original dimensions. Independent decode reads those dimensions and uses the same final resize. Its actual rates are 26-70% below ordinary init and are not close-rate controls; no matched-rate JPEG claim follows from this point. A later separate fixed q75 reference belongs to the completed-codec stage, not an initial quality sweep.','','| Image | Actual qualifying transform steps | Estimated MSE change at ordinary init bytes | Measured bracket |','| --- | --- | ---: | --- |']
    for r in a['comparisons']:
        bracket=r['bracket_at_ordinary_bytes']
        lines.append(f"| {r['image']} | {', '.join(map(str,r['actual_advantage_steps'])) or 'none'} | {format(r['interpolated_mse_change_percent'],'+.2f')+'%' if bracket else '-'} | {str(bracket['a'])+' -> '+str(bracket['b']) if bracket else 'none'} |")
    lines+=['','Actual gate conditions are 10% lower MSE with at most 5% extra bytes, or 10% fewer bytes with at most 2% extra MSE. Text step 256 saves 68.77% bytes at 1.29% extra source MSE; Cat step 128 saves 14.62% bytes and reduces MSE 23.14%. Sparse interpolation at ordinary initialization rate estimates -20.10% Googlewiki, -25.89% Cat, +11.20% Monet and -3.29% Flower. Interpolation is between measured quantizers, not an achievable equal-rate file. Cat/Flower are one coarse photo class, so text plus Cat satisfy the two-class gate. Monet and Flower limitations remain explicit.','','Runtime and reconstruction buffers, one warmup plus one timed creation/full RGB decode per fixed setting, common production prepare excluded:','','| Image | Kind / step | Encode ms | Decode ms | Coefficient slots / nonzeros | Signed canvas MB | One float coeff buffer MB | Traced decode peak MB |','| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for r in a['rows']:
        label=r['variant']+((' / '+str(r['step'])) if r['step'] is not None else '')
        counts=f"{r['coefficient_count']} / {r['nonzero_count']}" if r['coefficient_count'] is not None else '-'
        lines.append(f"| {r['image']} | {label} | {r['encode_seconds']*1000:.2f} | {r['decode_seconds']*1000:.2f} | {counts} | {r['canvas_bytes']/1e6:.3f} | {format(r['float_coefficient_buffer_bytes']/1e6,'.3f') if r['float_coefficient_buffer_bytes'] else '-'} | {r['traced_decode_peak']/1e6:.3f} |")
    lines+=['','Float buffers are working-size (around 3 MB each), while full photographic RGB output is 25.58 MB. A separate traced decode measures Python/NumPy allocations, not all native PIL storage; isolated whole-process measurements are in the completed results. All candidate steps retain a plausible working-size decode path at this stage. Initializer timings exclude shared prepare and are not whole-codec timings.','','The frozen integrated base is step 128 for every image and preset. It was declared before this screen, with no image-specific quantizer/budget table. A different step might change results, but the pass does not search for a rescue.']
    save('PBC_TRANSFORM_INIT_FEASIBILITY.md',lines)
    lines=['# Pass 25 completed transform-base results','','Reject the tested architecture as a general-purpose improvement. Outcome C/D: useful initialization-only capacity does not produce a reliable completed-file RD gain with the existing patch policy, and conventional JPEG dominates 5 of 8 hybrid points. No extension or repeated timing campaign.','','Research-only P25B is a 17-byte <4sIIBI> header (magic, complete P25I base length, raw spatial bytes, production entropy method, patch count), followed by the full base and generated-palette patch payload. Framing overhead is 41 bytes including the P25I header, before entropy-internal headers. Spatial records use existing patch syntax/channel bits 2/positive_bias=True; spatial entropy uses the unmodified production raw/LZMA selection. No three fabricated initial patches.','','The original model loads as legacy LearnedFiller: it has no begin_encode, running base-bit accounting or initialization-patch history. Verified exactly that class; factored policies reject instead of receiving false metadata. Owned local FillerHead/SearchState, the normal legacy proposal/feature/action path, release NumPy RNG, target, channel selection, additive int16 semantics and early stopping are retained. Ordinary Q50/HQ20 iterative budgets remain fixed; all hybrid patches are freshly optimized from the decoded transform canvas. The policy runs correctly but its efficacy from this residual distribution is empirical, not assumed. No retraining or production monkeypatch.','','Full input preparation, base encode/decode, refinement, framing/entropy, final conversion/resize and enabled original-source internal MSE are inside candidate encode timers. The decoder reconstructs from the actual file only. Ordinary defaults are freshly encoded and byte/pixel-identical to saved Pass17 controls. Base-only runs the same encoder with zero iterative budget; output exactly matches initial step 128. One warmed deterministic complete call per setting, alternating order, on i9-12900H P-core 12 with one numerical/FFT thread and Python 3.11.16/NumPy 2.4.6/Numba 0.68.0/Pillow 11.3.0/SciPy 1.17.1. Hashes/I/O/external scoring excluded. No rejected candidate gets three timing repetitions.','','| Image | Preset | Ordinary bytes / MSE | Step128 base-only bytes / MSE | Hybrid bytes / MSE | Rate change vs ordinary | MSE change |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
    for c in screen['comparisons']:
        name,preset=c['image'],c['preset'];o=point(name,preset,'ordinary');b=point(name,preset,'base_only');h=point(name,preset,'hybrid')
        lines.append(f"| {name} | {preset} | {o['bytes']:,} / {o['rgb_mse']:.3f} | {b['bytes']:,} / {b['rgb_mse']:.3f} | {h['bytes']:,} / {h['rgb_mse']:.3f} | {c['rate_change_percent']:+.2f}% | {c['mse_change_percent']:+.2f}% |")
    lines+=['','Only Googlewiki HQ strictly improves its same-preset default: -2.67% bytes and -0.44% MSE. Googlewiki Q pays 45.43% more for 1.38% lower MSE. Monet Q/HQ MSE worsens about 33%; Flower Q/HQ worsens 86.03%/29.78%, with much larger files. Cat Q trades 9.81% fewer bytes for 3.22% more MSE; Cat HQ is worse in both. This fails the frozen two-class meaningful-completed-RD gate with no useful classes, even though some initial-only results passed.','','Contribution of PBC refinement at the same frozen base:','','| Image / preset | Base bytes | Raw spatial bytes | Final spatial payload bytes | Patches | Full bpp | MSE reduction from step 128 base |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for c in screen['comparisons']:
        r=point(c['image'],c['preset'],'hybrid')
        lines.append(f"| {r['image']} / {r['preset']} | {r['base_bytes']:,} | {r['spatial_raw_bytes']:,} | {r['spatial_payload_bytes']:,} | {r['spatial_patches']} | {r['bpp']:.5f} | {-c['refinement_mse_change_percent']:.2f}% |")
    lines+=['','PBC patches are not ineffectual: they reduce source RGB MSE 31-72% versus the same coarse base. They are also not demonstrated compression-efficient: they dominate final bytes and fail the external/ordinary controls. Flower Quality is strictly dominated by the already measured step 64 transform-only base, reframed as an actual P25B zero-patch file:12,717 bytes/MSE 74.156 versus 43,121/MSE 80.801. This uses a predeclared A quantizer, no new transform encode or sweep. All other base64/128/256 reframed files and pixel checks are recorded in analysis.json.','','Conventional JPEG reference: one fixed quality 75 working-resolution file per image, with the same 14-byte original-size comment and final resizing. Encoder timing excludes common prepare for JPEG and is not a comparable full speed claim. No rate search. Actual sizes below hybrid rates are preserved; no equal-rate extrapolation.','','| Image | JPEG q75 bytes / source MSE | JPEG dominates hybrid Q | JPEG dominates hybrid HQ |','| --- | ---: | --- | --- |']
    for name in IMAGES:
        jpeg=next(r for r in screen['rows'] if r['image']==name and r['variant']=='jpeg');cs=[r for r in screen['comparisons'] if r['image']==name]
        lines.append(f"| {name} | {jpeg['bytes']:,} / {jpeg['rgb_mse']:.3f} | {next(r['jpeg_dominates'] for r in cs if r['preset']=='quality')} | {next(r['jpeg_dominates'] for r in cs if r['preset']=='high_quality')} |")
    lines+=['','JPEG strictly dominates Monet Q, both Cat points and both Flower points. Monet HQ is only about 0.08% lower MSE than JPEG while taking 2.86x its bytes; that remains a trade, not JPEG dominance. Both Googlewiki hybrids have lower MSE than the q75 JPEG at far higher bytes. No hybrid strictly dominates that JPEG point. Neither q1 nor q75 brackets any hybrid final rate, so a matched-rate JPEG conclusion cannot be invented. The bounded reference is sufficient to reject general superiority on 5 actual points, not to estimate a continuous JPEG frontier.','','Stronger ordinary controls include saved Q/HQ, Quality-p10, HQ-p10, targeted budgets and Googlewiki 500k, all hash-checked with unchanged production source. Actual near-rate comparisons and conservative minimum measured-chord estimates remain distinct:','','| Image / preset | Strongest actual ordinary within 5% | Signed rate gap | MSE change vs actual point | Bracket estimate MSE change |','| --- | --- | ---: | ---: | ---: |']
    for r in analysis['comparisons']:
        near=r['actual_ordinary_within5pct'];estimate=r['interpolated_ordinary_mse_change_percent']
        lines.append(f"| {r['image']} / {r['preset']} | {near['preset'] if near else 'none'} | {format(near['signed_rate_gap_percent'],'+.3f')+'%' if near else '-'} | {format(near['mse_change_percent'],'+.3f')+'%' if near else '-'} | {format(estimate,'+.3f')+'%' if estimate is not None else '-'} |")
    lines+=['','Googlewiki Q has a narrow actual lead versus ordinary HQ-p10: +0.088% bytes/-3.25% MSE, distinct from its much worse comparison to default Quality. Googlewiki HQ has the small actual default win. Broad brackets including the stronger500k point estimate regressions; those sparse chords are not achievable single-file controls. No extrapolation or general matched-rate improvement is claimed.','','Full-call timing, one-pass feasibility observations:','','| Image / preset | Ordinary encode / decode ms | Hybrid encode / decode ms | Encode change | Decode change |','| --- | ---: | ---: | ---: | ---: |']
    for c in screen['comparisons']:
        o=point(c['image'],c['preset'],'ordinary');h=point(c['image'],c['preset'],'hybrid')
        lines.append(f"| {c['image']} / {c['preset']} | {o['encode_seconds']*1000:.2f} / {o['decode_seconds']*1000:.2f} | {h['encode_seconds']*1000:.2f} / {h['decode_seconds']*1000:.2f} | {c['encode_change_percent']:+.2f}% | {c['decode_change_percent']:+.2f}% |")
    lines+=['','Observed encode changes span roughly -20% to +18%, decode changes -5% to +33%. These are not statistically confirmed speed improvements; faster poor-quality points do not become RD wins. Googlewiki HQ misses the preferred 15% decode overhead, while several other points approach it. No HF extrapolation.','','Isolated decoder memory: one fresh process per HQ file, same tiny ordinary/working-DCT/P21S warmups, then one actual target decode. Pre-call/peak/final RSS retained; native peak_wset captured before hashes. Imports and allocator retention included. MiB uses 2^20 bytes.','','| Image | Variant | Pre-call RSS MiB | Peak MiB | Peak above pre-call MiB | RGB MSE |','| --- | --- | ---: | ---: | ---: | ---: |']
    for r in memory['rows']:lines.append(f"| {r['image']} | {r['variant']} | {r['baseline_rss']/1048576:.2f} | {r['peak_rss']/1048576:.2f} | {r['peak_above_baseline']/1048576:.2f} | {r['rgb_mse']:.3f} |")
    lines+=['','The working-resolution decoder keeps memory close to ordinary PBC on photos; small images add roughly 4-7 MiB in process peak. Cat hybrid peaks about 151 MiB versus 501 MiB for the frozen optimized P21S decoder. Their errors differ substantially (about 296 versus 91), so this is a memory-scale comparison, not matched-RD superiority. A working float coefficient buffer is around 3 MB, compared with about 102 MB for Cat original-resolution P21S. No P21S code or decoder was modified.','','Validation covers 48 recorded initializer/ordinary/base-only/hybrid/JPEG files; all bytes/pixels/dimensions/MSE and repeat decodes match, with internal MSE against the true source. Eleven fixtures include odd/1x1 deterministic bases, int16 coefficient endpoints and actual additive wrap from 32767 to -32768. Thirty-eight malformed/resource/magic cases reject, including sparse entropy counts/expansion/trailing bytes, raw patch limits, channel/geometry/cell bounds and canvas overflow. Two fresh processes decode P25B without policy/source/ordinary encoding. The ordinary decoder rejects both experimental magics.','','Disposition: preserve the bounded research implementation and negative result; no integration, policy redesign, extra quantizer/budget search, extension or broad benchmark. The observed bottleneck is efficient refinement from the new base, with poor generalization and expensive spatial payloads. Model distribution shift, block artifacts and rate allocation are possible explanations, not isolated causes. These data reject this fixed scalar-DCT/XZ0/legacy-refinement formulation, not every transform-initialized architecture.']
    save('PBC_TRANSFORM_BASE_RD_RESULTS.md',lines)
    lines=['# Pass 25 summary','','Outcome C/D: transform initialization has useful isolated capacity, but the completed transform-plus-PBC architecture fails. Keep the experiment isolated and stop before additional images, timing repetitions or redesign.','','1. Ordinary standalone initialization costs 11,771/7,475/3,968/4,065 bytes on Googlewiki/Monet/Cat/Flower. It leaves source RGB MSE 1559.37/203.50/581.72/276.34. Its separately compressed size is roughly 5-14% of corresponding full Q/HQ files, not additive compressed-byte ownership.','2. The fixed 64/128/256 DCT screen passes on text plus photography: actual Cat step 128 is 14.62% smaller and 23.14% lower MSE; Googlewiki step 256 is 68.77% smaller at 1.29% more MSE. Bracket estimates at ordinary init bytes are -20.10% Googlewiki, -25.89% Cat, +11.20% Monet, -3.29% Flower. Initializer efficiency is not universal.','3. One low-rate JPEG q1 reference per image was measured; it is 26-70% below ordinary init bytes and is not a matched-rate control. Transform points can beat this low-quality JPEG point, which does not establish superiority over conventional JPEG at the final hybrid rate.','4. The actual legacy policy runs without initialization history; no fake three-patch metadata or retraining. Fresh PBC refinement from decoded step 128 bases reduces MSE 31-72% relative to the same coarse base, but costs large spatial payloads. Merely adding patches is not evidence of compression efficiency.','5. Completed results: only Googlewiki HQ strictly beats its default (-2.67% rate/-0.44% MSE). Googlewiki Q pays 45.43% more for 1.38% lower MSE; it has a narrow near-rate lead versus HQ-p10 (+0.088% bytes/-3.25% MSE). Monet Q/HQ MSE rises about 33%; Flower Q/HQ rises 86%/30% with larger files. Cat Q saves 9.81% rate at 3.22% more MSE, and Cat HQ loses both metrics.','6. The fixed working JPEG q75 point strictly dominates 5/8 hybrids. Monet HQ has only about 0.08% lower MSE than JPEG at 2.86x bytes; Googlewiki uses much more rate for lower MSE. No hybrid dominates q75 JPEG, and no JPEG equal-rate claim is supported. Flower Quality is additionally dominated by the already measured step 64 transform-only base (12,717/MSE 74.156 versus 43,121/MSE 80.801).','7. Complete one-pass encode changes are about -20% to +18%, decode -5% to +33%. Only research feasibility timing was warranted; no three-repeat speed claim or HF transfer. The fixed decoder adds working-size inverse transform and existing PBC patches, followed by normal source-size RGB output.','8. Isolated HQ decoder peaks are about 124.5/123.5/150.8/152.1 MiB for Googlewiki/Monet/Cat/Flower, close to ordinary 117.4/119.2/151.3/151.5 MiB. Frozen P21S Cat peaks 500.6 MiB but has much better MSE 91 versus this hybrid 296. Working-resolution transforms are cheaper in memory, not a proved better RD architecture.','9. All 48 measured files, 11 boundary/determinism/signed-wrap fixtures, 38 malformed/resource/magic rejections and two fresh model-free file-only decoders pass. Format P25I (24-byte header) holds the base; P25B adds 17-byte framing and ordinary generated-palette records with fixed positive-bias semantics. All coefficient/patch/entropy/side-information bytes count.','10. Initializer-only benefits do not survive refinement consistently. The existing learned spatial representation remains rate-inefficient from this fixed base; causes were not isolated to policy alone. No second base quantizer, JPEG quality or patch-budget rescue was run. Mario64/Eiffel and unseen-image generalization remain untested because the completed gate failed.','11. This tested formulation does not justify another optimization pass or integration. Preserve the smaller working-decoder insight and negative RD evidence. A future architectural choice should demonstrate complementarity against transform-only and conventional coding, rather than retain spatial patches by default. No followup was launched.','','Reproduce with Python 3.11 and ../research_pass17/requirements.txt, original hpt_data, saved Pass17 streams/ordinary controls and Pass18 Googlewiki 500k control with recorded hashes. The script order below enforces the A/C gates; generated files/arrays/caches remain ignored.','','```','research_pass16/.venv/Scripts/python.exe research_pass25/feasibility.py','research_pass16/.venv/Scripts/python.exe research_pass25/screen.py','research_pass16/.venv/Scripts/python.exe research_pass25/analyze.py','research_pass16/.venv/Scripts/python.exe research_pass25/memory.py','research_pass16/.venv/Scripts/python.exe research_pass25/validate.py','research_pass16/.venv/Scripts/python.exe research_pass25/report.py','```','','screen.py --extend is guarded by the failed completed gate and was not run. Initial q1 and completed q75 JPEG references are separate fixed stage points, not a quality sweep. Saved source/config/model/input/file/pixel hashes, raw and compressed payload accounting, memory process records and compact measurements accompany the reports.','','Practical codec/model/v0, earlier frozen experiments including P21S/Pass22, public defaults, HF and staging are unchanged. ZIP SHA256: 08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591. Only focused research source/tests/evidence is committed/pushed to research/experiments. Final verified research commit/GitHub HEAD is supplied in the chat handoff; no protected branch, release/tag or deployment.']
    save('PBC_PASS25_SUMMARY.md',lines)
    for filename,rows in (('initializers.csv',a['rows']),('files.csv',screen['rows'])):
        fields=['image','preset','variant','step','bytes','bpp','rgb_mse','working_component_mse','working_rgb_mse','encode_seconds','decode_seconds','coefficient_count','nonzero_count','base_bytes','spatial_raw_bytes','spatial_payload_bytes','spatial_patches','stream_sha256','pixels_sha256']
        with (HERE/filename).open('w',newline='',encoding='utf-8') as file:
            writer=csv.DictWriter(file,fieldnames=fields,extrasaction='ignore',lineterminator='\n');writer.writeheader();writer.writerows(rows)
    result=meta();result.update(evidence_sha256={p.name:sha(p.read_bytes()) for p in HERE.iterdir() if p.suffix in ('.json','.csv') and p.name!='provenance.json'},prior_control_evidence_sha256=analysis['control_evidence_sha256'],initialization_passed=True,integrated_screen_passed=False,extension_executed=False,three_repeat_timing_executed=False,integrated_base_step=128,format={'base_magic':'P25I','base_header_bytes':base.HEADER.size,'hybrid_magic':'P25B','hybrid_header_bytes':hybrid.HEADER.size,'sparse':'R21V/XZ0','spatial':'ordinary generated palettes,channelbits 2,positive_bias=True;production entropy'},staged_zip_sha256_unchanged='08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591')
    write('provenance.json',result)
    print('reports written; initializer pass, completed architecture failure; no extension/repeated timings',flush=True)


if __name__=='__main__':main()
